func FindEstado(ctx context.Context, exec boil.ContextExecutor, estID int, selectCols ...string) (*Estado, error) {
	estadoObj := &Estado{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from `estado` where `est_id`=?", sel,
	)

	q := queries.Raw(query, estID)

	err := q.Bind(ctx, exec, estadoObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "models: unable to select from estado")
	}

	if err = estadoObj.doAfterSelectHooks(ctx, exec); err != nil {
		return estadoObj, err
	}

	return estadoObj, nil
}

